nasal.load:

var nodeName = cmdarg().getPath();

print("Loading WWII-Heinkel-He-280 ", nodeName);

if ( bombable.check_overall_initialized (nodeName) ) {
  return;
}
var object_init = func() {
  thisNodeName = cmdarg().getPath();

  var bombableObject = {

    objectNodeName : thisNodeName,
    objectNode     : props.globals.getNode(thisNodeName),
    updateTime_s   : 1/3,
    altitudes : {
      wheelsOnGroundAGL_m : 0 ,
      minimumAGL_m : 0,
      maximumAGL_m : 0,
      crashedAGL_m : -1,
    },
    velocities : {
      maxSpeedReduce_percent                       : 0.5,
      minSpeed_kt                                  : 0,
      cruiseSpeed_kt                               : 0,
      attackSpeed_kt                               : 0,
      maxSpeed_kt                                  : 0,
      damagedAltitudeChangeMaxRate_meterspersecond : 30,

      diveTerminalVelocities: {
        point1: { airspeed_kt : 220, vertical_speed_fps : - 35.4},
        point2: { airspeed_kt : 250, vertical_speed_fps : - 125.1},
        point3: { airspeed_kt : 270, vertical_speed_fps : - 143.0},
        point4: { airspeed_kt : 280, vertical_speed_fps : - 173.9},
      },
      climbTerminalVelocities: {
